    if not all(i in aa and j in bb and aa[i].GetAtomicNum()==bb[j].GetAtomicNum() for i,j in pairs):return False
    for bo in a.GetBonds():
        i,j=bo.GetBeginAtom().GetAtomMapNum(),bo.GetEndAtom().GetAtomMapNum()
