def merge(a,b):
    a=deepcopy(a)
    for k,v in b.items():
        if k=='required':a[k]=list(dict.fromkeys(a.get(k,[])+v))
        elif isinstance(v,dict) and isinstance(a.get(k),dict):a[k]=merge(a[k],v)
